target.css:
:root {
  --ink: #211b34;
  --panel: #fffdf7;
  --line: #e6ddcf;
  --violet: #5542a7;
  --violet-soft: #eeeaff;
  --lime: #d7ee76;
  --coral: #e96353;
  --muted: #756f7e;
  --soft: #f6f1e8;
  --white: #ffffff;
}

.market-card,
.market-card * {
  box-sizing: border-box;
}

.market-card {
  width: 500px;
  overflow: hidden;
  border: 1px solid var(--line);
  border-radius: 18px;
  background: var(--panel);
  color: var(--ink);
}

.card-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 13px 16px;
  border-bottom: 1px solid var(--line);
}

.vendor-mark {
  display: flex;
  align-items: center;
  gap: 10px;
}

.lantern {
  display: grid;
  width: 32px;
  height: 32px;
  place-items: center;
  border-radius: 10px;
  background: var(--violet-soft);
  font-size: 18px;
}

.eyebrow {
  margin: 0 0 2px;
  color: var(--muted);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.9px;
}

.vendor-mark h1 {
  margin: 0;
  font-size: 17px;
  line-height: 1.1;
}

.live-chip,
.paid {
  border-radius: 999px;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.5px;
}

.live-chip {
  padding: 5px 8px;
  background: var(--lime);
  color: var(--ink);
}

.metrics {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  padding: 10px 16px;
  gap: 8px;
}

.stat {
  display: flex;
  flex-direction: column;
  gap: 3px;
  padding: 8px 10px;
  border-radius: 10px;
  background: var(--soft);
}

.stat span,
.pickup-label {
  color: var(--muted);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.35px;
}

.stat strong {
  font-size: 16px;
  line-height: 1.1;
}

.accent-stat {
  background: var(--violet);
}

.accent-stat span,
.accent-stat strong {
  color: var(--white);
}

.checkout-grid {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 142px;
  gap: 10px;
  padding: 0 16px 12px;
}

.order-panel {
  overflow: hidden;
  border: 1px solid var(--line);
  border-radius: 12px;
}

.panel-title,
.order-total {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 8px 10px;
}

.panel-title {
  border-bottom: 1px solid var(--line);
  background: var(--soft);
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.45px;
}

.paid {
  padding: 3px 6px;
  background: var(--lime);
  color: var(--ink);
  font-size: 8px;
}

.order-lines {
  display: grid;
  margin: 0;
  padding: 5px 10px;
  gap: 2px;
  list-style: none;
}

.order-lines li {
  display: grid;
  grid-template-columns: 24px 1fr auto;
  align-items: center;
  min-width: 0;
  padding: 3px 0;
  font-size: 12px;
}

.qty {
  color: var(--violet);
  font-weight: 800;
}

.order-lines strong,
.order-total strong {
  font-size: 12px;
}

.order-total {
  border-top: 1px solid var(--line);
  color: var(--violet);
  font-size: 12px;
  font-weight: 800;
}

.order-total strong {
  font-size: 15px;
}

.pickup-card {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 4px;
  border-radius: 12px;
  background: var(--coral);
  color: var(--white);
  text-align: center;
}

.pickup-icon {
  font-size: 17px;
}

.pickup-label,
.pickup-note {
  color: var(--white);
}

.pickup-label {
  font-size: 8px;
}

.pickup-card strong {
  font-size: 22px;
  line-height: 1;
}

.pickup-note {
  font-size: 9px;
}

.actions {
  display: flex;
  justify-content: flex-end;
  gap: 8px;
  padding: 10px 16px;
  border-top: 1px solid var(--line);
}

.actions button {
  border: 1px solid var(--violet);
  border-radius: 8px;
  padding: 7px 10px;
  font-size: 11px;
  font-weight: 800;
}

.secondary {
  background: var(--white);
  color: var(--violet);
}

.primary {
  background: var(--violet);
  color: var(--white);
}

